        Connection::session().await?
    } else {
        Connection::system().await?
    };

    let introspectable = zbus::Proxy::new(
        &connection,
        PLUGINS_ROOT_NAME,
        PLUGINS_ROOT_PATH,
        "org.freedesktop.DBus.Introspectable",
    )
    .await
    .map_err(|e| anyhow::anyhow!("cannot reach {PLUGINS_ROOT_NAME} on the {bus_label} bus: {e}"))?;

    let xml: String = introspectable
        .call("Introspect", &())
        .await
        .map_err(|e| anyhow::anyhow!("introspecting {PLUGINS_ROOT_NAME} failed on the {bus_label} bus: {e}"))?;

