        .parse()
        .map_err(|e| anyhow::anyhow!("invalid footprint header value: {e}"))?;
    let trace_meta: MetadataValue<Ascii> = trace_id
        .parse()
        .map_err(|e| anyhow::anyhow!("invalid trace-id header value: {e}"))?;

