    let ports_csv = args
        .port
        .iter()
        .map(|p| p.to_string())
        .collect::<Vec<_>>()
        .join(",");

    let request = CallMethodRequest {
        plugin_id: TARGET_PLUGIN.to_string(),
        object_path: object_path.clone(),
        interface_name: String::new(),
        method_name: CREATE_METHOD.to_string(),
        arguments: vec![string_value(&args.name), string_value(&ports_csv)],
        actor_id: String::new(), // resolved from the sled inside MutationEngine
        capability_id: String::new(),
