/// Read the Ghostbridge accountability headers from the live Identity Sled.
///
/// Layout (152-byte repr(C)): `hashed_footprint [u8;32]` at offset 40,
/// `trace_id [u8;16]` at offset 72. Both must match the sled the interceptor
/// reads, so we source them from the same tmpfs file rather than a projection.
fn read_sled_identity() -> anyhow::Result<(String, String)> {
    let bytes = std::fs::read(SLED_PATH)
        .map_err(|e| anyhow::anyhow!("cannot read Identity Sled at {SLED_PATH}: {e}"))?;
    if bytes.len() < 88 {
        anyhow::bail!(
            "Identity Sled at {SLED_PATH} is {} bytes; expected at least 88",
            bytes.len()
        );
    }
    let footprint = &bytes[40..72];
    let trace_id = &bytes[72..88];
    if footprint.iter().all(|&b| b == 0) || trace_id.iter().all(|&b| b == 0) {
        anyhow::bail!(
            "Identity Sled is not provisioned (zero footprint or trace-id); \
             cannot authenticate to the Ghostbridge gate"
        );
    }
    Ok((hex::encode(footprint), hex::encode(trace_id)))
}

